oxy_webhelp_navlinks = {"custom_agents_deployed_agent_cloud-d39307e62709":{"topics":[{"title":"Prerequisites for custom agents","shortdesc":"<p class=\"shortdesc\">Before you connect custom agents, ensure that your environment         meets the required account, network, and configuration prerequisites.<\/p>","href":"agent_cloud\/prerequisites_custom_agents_agent_cloud.html","attributes":{"data-id":"prerequisites_custom_agents_agent_cloud"},"menu":{"hasChildren":false},"tocID":"prerequisites_custom_agents_agent_cloud-d39307e62723","topics":[]},{"title":"How model gateways work","shortdesc":"<p class=\"shortdesc\">Model gateways are the fundamental infrastructure components that enable <span class=\"ph\">Agent Cloud<\/span> to govern, monitor, and secure your AI agent         interactions.<\/p>","href":"agent_cloud\/understand_how_model_gateways_work.html","attributes":{"data-id":"understand_how_model_gateways_work"},"menu":{"hasChildren":false},"tocID":"understand_how_model_gateways_work-d39307e62734","topics":[]},{"title":"Rubrik AI gateway","shortdesc":"<p class=\"shortdesc\">The Rubrik AI gateway is a Rubrik-hosted proxy between your custom agents and model         providers. It records every prompt, response, and tool call, and blocks the ones that break         a block policy before they reach the model or the agent.<\/p>","href":"agent_cloud\/custom_agents_built_in_model_gateway.html","attributes":{"data-id":"custom_agents_built_in_model_gateway"},"menu":{"hasChildren":false},"tocID":"custom_agents_built_in_model_gateway-d39307e62748","next":"custom_agents_built_in_model_gateway-d39307e62748"},{"title":"LiteLLM","shortdesc":"<p class=\"shortdesc\">If your custom agents already route their model traffic through a LiteLLM proxy, the Rubrik plugin sends that traffic to <span class=\"ph\">Agent Cloud<\/span> for recording and real-time policy enforcement. Review the capabilities, requirements, limitations, and responsibilities before you connect the proxy.<\/p>","href":"agent_cloud\/custom_agents_existing_model_gateways.html","attributes":{"data-id":"custom_agents_existing_model_gateways"},"menu":{"hasChildren":false},"tocID":"custom_agents_existing_model_gateways-d39307e62839","next":"custom_agents_existing_model_gateways-d39307e62839"}]}};